import {ArrowLeft,ArrowRight} from 'lucide-react';
import {getRoadmaps,getExtraRoadmaps,gradeOptions,type Roadmap} from '@/lib/roadmaps';
import CompanionStories from './CompanionStories';
export default function DiscoveryPage({tab,grade,page,onGrade,onPage,onHome,onRoadmap}:{tab:string;grade:number;page:number;onGrade:(n:number)=>void;onPage:(n:number)=>void;onHome:()=>void;onRoadmap:(r:Roadmap)=>void}){const isRoadmap=tab==='roadmaps';const current=page===2?2:1;const all=[...getRoadmaps(grade),...getExtraRoadmaps(grade)];return <div className="member-page discovery-page"><header className="member-heading member-heading-compact"><h1>{isRoadmap?`Lộ trình học Toán lớp ${grade}`:'Câu chuyện đồng hành'}</h1>{isRoadmap&&<div className="member-toolbar"><label htmlFor="discovery-grade">Lớp đang chọn</label><select id="discovery-grade" value={grade} onChange={e=>onGrade(Number(e.target.value))}>{gradeOptions.map(g=><option value={g} key={g}>Lớp {g}</option>)}</select></div>}<button className="button soft" onClick={onHome}><ArrowLeft size={15}/>Về trang chủ</button></header>{isRoadmap?<><p className="sidebar-note">6 lộ trình mẫu, chờ giáo viên thẩm định trước khi phát hành.</p><div className="section-card-grid">{all.slice((current-1)*4,current*4).map((r,i)=><article className="section-card" key={r.id}><div className="section-card-heading"><span className="sample-badge">LỘ TRÌNH MINH HỌA</span><h3>{r.title}</h3><p>{r.summary}</p></div><div className="section-card-image"><img src={['/assets/toan/foundation-v6.png','/assets/toan/geometry-v3.webp','/assets/toan/exam-v3.webp'][i%3]} alt="Minh họa lộ trình học Toán"/></div><div className="section-card-body"><ol>{r.steps.map(s=><li key={s}>{s}</li>)}</ol><button className="button primary" onClick={()=>onRoadmap(r)}>Xem chi tiết<ArrowRight size={15}/></button></div></article>)}</div></>:<CompanionStories catalog page={current}/>}<nav className="catalog-pagination" aria-label={`Phân trang ${isRoadmap?'lộ trình':'câu chuyện'}`}><span>Trang {current}/2 · 4 mục mỗi trang · Dữ liệu mẫu</span><div><button onClick={()=>onPage(1)} disabled={current===1} aria-label="Trang trước">‹</button>{[1,2].map(n=><button key={n} onClick={()=>onPage(n)} aria-current={current===n?'page':undefined} aria-label={`Trang ${n}`}>{n}</button>)}<button onClick={()=>onPage(2)} disabled={current===2} aria-label="Trang sau">›</button></div></nav></div>}
